import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"IndiaBulls Securities","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/indiabulls-securities.md","filePath":"connect-brokers/brokers/indiabulls-securities.md"}'),o={name:"connect-brokers/brokers/indiabulls-securities.md"};function n(i,e,l,p,d,c){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="indiabulls-securities" tabindex="-1">IndiaBulls Securities <a class="header-anchor" href="#indiabulls-securities" aria-label="Permalink to &quot;IndiaBulls Securities&quot;">​</a></h1><p>IndiaBulls Securities provides API access through the XTS (Symphony Fintech) platform, served from <code>https://xts.ibullssecurities.com</code>. Tradeboard registers this integration as the broker <code>ibulls</code>, and its plugin talks to two XTS endpoints: the Interactive API for orders, positions and holdings, and the Market Data API for quotes, depth and historical candles.</p><hr><h3 id="step-1-create-api-applications" tabindex="-1">Step 1: Create API Applications <a class="header-anchor" href="#step-1-create-api-applications" aria-label="Permalink to &quot;Step 1: Create API Applications&quot;">​</a></h3><p>Log in to the IndiaBulls XTS developer dashboard at <a href="https://xts.ibullssecurities.com" target="_blank" rel="noreferrer">https://xts.ibullssecurities.com</a> with your IndiaBulls credentials.</p><p>Once logged in:</p><ol><li>Go to <code>My App</code> &gt; <code>Create New Application</code></li><li>Create two separate apps:</li></ol><ul><li><strong>Interactive Order API</strong></li><li><strong>Market Data API</strong></li></ul><p><strong>Details to Fill:</strong></p><ul><li><strong>App Name</strong>: Tradeboard</li><li><strong>App Description</strong>: Tradeboard</li><li><strong>Redirect URL: (leave it empty)</strong></li><li><strong>Company Name</strong>: Tradeboard (or your own)</li><li>Choose the correct <strong>API Package</strong> depending on the app (Order or Market Data).</li></ul><p>Once submitted, wait for approval from the broker. After approval, the status will turn <strong>Active</strong>.</p><hr><h3 id="step-2-setup-environment-variables" tabindex="-1">Step 2: Setup Environment Variables <a class="header-anchor" href="#step-2-setup-environment-variables" aria-label="Permalink to &quot;Step 2: Setup Environment Variables&quot;">​</a></h3><p>Each app issues its own App Key and Secret Key. The Interactive app&#39;s pair goes into the plain variables, the Market Data app&#39;s pair into the <code>_MARKET</code> variables. Refer to the <code>.sample.env</code> file in your Tradeboard folder and prepare your <code>.env</code> as follows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Broker Configuration</span></span>
<span class="line"><span>BROKER_API_KEY = &#39;YOUR_BROKER_ORDER_API_KEY&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;YOUR_ORDER_API_SECRET&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BROKER_API_KEY_MARKET = &#39;YOUR_BROKER_MARKET_API_KEY&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET_MARKET = &#39;YOUR_BROKER_MARKET_API_SECRET&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/ibulls/callback&#39;</span></span></code></pre></div><p>Replace the values with actual credentials shown on your developer dashboard once approved.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The broker code in the redirect URL is <code>ibulls</code>, not <code>indiabulls</code>. Tradeboard reads the active broker out of <code>REDIRECT_URL</code>, so a different spelling is rejected as an invalid broker.</p></div><hr><h3 id="step-3-start-tradeboard" tabindex="-1">Step 3: Start Tradeboard <a class="header-anchor" href="#step-3-start-tradeboard" aria-label="Permalink to &quot;Step 3: Start Tradeboard&quot;">​</a></h3><p>Once all environment variables are set and both apps are <strong>Active</strong>, start Tradeboard and click <strong>Connect</strong> on the IndiaBulls Securities broker page. There is no broker login screen to complete: Tradeboard posts your App Key and Secret Key straight to the XTS session endpoint and receives the interactive token, the market data feed token and your user id in one step.</p><p>This completes the integration process for IndiaBulls Securities with Tradeboard.</p><p>Integrating Tradeboard with the IndiaBulls XTS API lets you automate order execution and consume real-time market data from one place. Always ensure secure handling of API credentials, implement proper error handling, and monitor your integration to maintain reliability and compliance.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/ibulls/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,25)])])}const b=a(o,[["render",n]]);export{h as __pageData,b as default};
